[
  {
    "op": "add",
    "collection": "nodes",
    "id": "source-4",
    "value": {
      "type": "source",
      "text": "The steward chooses what the next work should be. After I have chosen, the orchestrator can insert the record for that already chosen work. Also, the orchestrator may ask me before stopping. Please capture that, without broadening it.",
      "status": "recorded",
      "meta": {
        "source_kind": "verbatim",
        "speaker": "Blake",
        "note": "First-person 'I' and 'me' refer to the speaker, Blake. Not resolved to steward-role or an operator role."
      }
    }
  },
  {
    "op": "add",
    "collection": "nodes",
    "id": "orchestrator-inserts-chosen-record",
    "value": {
      "type": "claim",
      "text": "After the next-work choice has been made, the orchestrator can insert the record for that already chosen work. Inserting the record is distinct from choosing the work.",
      "status": "proposed",
      "meta": {
        "review_state": "current",
        "sources": [
          "source-4"
        ],
        "rationale": "Speaker wording: 'After I have chosen, the orchestrator can insert the record for that already chosen work.' Modality is permissive ('can'). Who 'I' denotes (Blake personally, or the steward role) is unresolved; the claim is left proposed pending that answer.",
        "actor_scope": "unresolved"
      }
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "link-5",
    "value": {
      "from": "orchestrator-inserts-chosen-record",
      "type": "about",
      "to": "orchestrator-role"
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "link-6",
    "value": {
      "from": "orchestrator-inserts-chosen-record",
      "type": "governs",
      "to": "create-record"
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "source-orchestrator-inserts-chosen-record-0",
    "value": {
      "from": "orchestrator-inserts-chosen-record",
      "type": "extracted-from",
      "to": "source-4"
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "link-7",
    "value": {
      "from": "orchestrator-inserts-chosen-record",
      "type": "depends-on",
      "to": "steward-next-work",
      "meta": {
        "note": "Record insertion applies only to work already chosen; the choice itself is governed by steward-next-work."
      }
    }
  },
  {
    "op": "add",
    "collection": "nodes",
    "id": "orchestrator-may-ask-before-stopping",
    "value": {
      "type": "claim",
      "text": "The orchestrator may ask the speaker (Blake) before stopping.",
      "status": "proposed",
      "meta": {
        "review_state": "current",
        "sources": [
          "source-4"
        ],
        "rationale": "Speaker wording: 'the orchestrator may ask me before stopping.' 'May' is permissive, not a requirement to consult. 'Me' is Blake; whether Blake is the operator referenced in the consultation question is unresolved. 'Stopping' is not narrowed to degraded work or a failed terminal result.",
        "actor_scope": "unresolved"
      }
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "link-8",
    "value": {
      "from": "orchestrator-may-ask-before-stopping",
      "type": "about",
      "to": "orchestrator-role"
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "link-9",
    "value": {
      "from": "orchestrator-may-ask-before-stopping",
      "type": "governs",
      "to": "end-attempt"
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "source-orchestrator-may-ask-before-stopping-0",
    "value": {
      "from": "orchestrator-may-ask-before-stopping",
      "type": "extracted-from",
      "to": "source-4"
    }
  },
  {
    "op": "add",
    "collection": "edges",
    "id": "link-10",
    "value": {
      "from": "orchestrator-may-ask-before-stopping",
      "type": "answers",
      "to": "consultation",
      "meta": {
        "coverage": "partial",
        "note": "Establishes that asking is permitted. Does not settle whether consultation is mandatory before ending degraded work, nor the configured-threshold alternative."
      }
    }
  }
]

